output_text:
[
  {
    "id": "take_entry_cart",
    "text": "A shopper is obliged to take the cart from the entry cart station before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entry_cart_event": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart_event"
    }
  },
  {
    "id": "no_hand_carried_goods",
    "text": "Items must not be carried by hand; shelf items should only be picked up while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "pickup_without_cart"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_nw_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the northwest return bay.",
    "abstraction": {
      "state_properties": {
        "northwest_return_bay": "at(0,1)",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "cart_returned_to_nw_bay": {
          "pre": {
            "and": [
              "northwest_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned_to_nw_bay"
    }
  },
  {
    "id": "leave_cart_only_at_bay",
    "text": "A cart may be put down only at the designated northwest return bay.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return_bay": "at(0,1)",
        "outside_cart_return_bay": {
          "not": "designated_cart_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "A shopper may exit only after the cart has been left parked at the return bay, and may not exit while still pushing the cart.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cart_returned"
        }
      },
      "events": {
        "bad_exit_with_unreturned_cart": {
          "pre": {
            "and": [
              "EXIT",
              {
                "or": [
                  "hasCart",
                  "cart_not_returned"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "bad_exit_with_unreturned_cart"
    }
  },
  {
    "id": "no_east_on_west_wall_with_cart",
    "text": "While pushing a cart on the west-wall return lane, the shopper must continue north or stop to return the cart rather than turn east.",
    "abstraction": {
      "state_properties": {
        "west_wall_return_lane": {
          "or": [
            "at(0,1)",
            "at(0,2)",
            "at(0,3)",
            "at(0,4)"
          ]
        },
        "pushing_cart_on_west_wall": {
          "and": [
            "hasCart",
            "west_wall_return_lane"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pushing_cart_on_west_wall",
          "E"
        ]
      }
    }
  },
  {
    "id": "no_south_from_middle_shelves_with_cart",
    "text": "Cart traffic is not allowed to turn south from the middle shelf cells, although pedestrians without carts may do so.",
    "abstraction": {
      "state_properties": {
        "middle_shelf_cell": {
          "or": [
            "at(2,4)",
            "at(3,4)",
            "at(2,2)",
            "at(3,2)"
          ]
        },
        "cart_at_middle_shelf": {
          "and": [
            "hasCart",
            "middle_shelf_cell"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_at_middle_shelf",
          "S"
        ]
      }
    }
  },
  {
    "id": "turn_back_from_east_shelf_with_cart",
    "text": "At the east-side shelf station, a shopper with a cart must turn back west rather than continue east or south.",
    "abstraction": {
      "state_properties": {
        "east_side_shelf_station": {
          "or": [
            "at(6,4)",
            "at(6,2)"
          ]
        },
        "cart_at_east_side_shelf": {
          "and": [
            "hasCart",
            "east_side_shelf_station"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_at_east_side_shelf",
          {
            "or": [
              "E",
              "S"
            ]
          }
        ]
      }
    }
  }
]
